		const live = this.live;
		if (!live) return;
		const objects = this.setup.objects;
		if (this.document.scene.recipe !== "projectiles" || !objects.muzzle) return;
		const mesh = new Mesh(objects.projectileGeometry, objects.projectileMaterial);
		objects.muzzle.getWorldPosition(mesh.position);
		this.scene.add(mesh);
